INSERT INTO storage.buckets (id, name, public) VALUES ('comparison-assets', 'comparison-assets', false) ON CONFLICT (id) DO NOTHING; CREATE POLICY "comparison_assets_select_own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'comparison-assets' AND auth.uid()::text = (storage.foldername(name))[1]); CREATE POLICY "comparison_assets_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'comparison-assets' AND auth.uid()::text = (storage.foldername(name))[1]); CREATE POLICY "comparison_assets_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'comparison-assets' AND auth.uid()::text = (storage.foldername(name))[1]); CREATE POLICY "comparison_assets_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'comparison-assets' AND auth.uid()::text = (storage.foldername(name))[1]);